import React, { useState, useEffect, useMemo } from "react";
import {
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from "recharts";

export default function SeedCatalog() {
  const [data, setData] = useState([]);
  const [search, setSearch] = useState("");
  const [marketFilter, setMarketFilter] = useState("all");
  const [selected, setSelected] = useState([]);
  const [xTrait, setXTrait] = useState("yield_kg_ha");
  const [yTrait, setYTrait] = useState("maturity_days");
  const [activeVariety, setActiveVariety] = useState(null);

  // Load real JSON
  useEffect(() => {
    fetch("/seed-catalog/data/uog-varieties.json")
      .then((res) => res.json())
      .then((json) => setData(json));
  }, []);

  // Trait options
  const traitOptions = [
    { key: "yield_kg_ha", label: "Yield (kg/ha)" },
    { key: "maturity_days", label: "Maturity (days)" },
    { key: "seed_weight_g", label: "Seed weight (g)" },
    { key: "harvestability", label: "Harvestability" },
  ];

  // Market classes
  const marketClasses = useMemo(() => {
    const s = new Set(data.map((d) => d.marketClass));
    return ["all", ...Array.from(s)];
  }, [data]);

  // Filtering
  const filtered = useMemo(() => {
    return data.filter(
      (d) =>
        (marketFilter === "all" || d.marketClass === marketFilter) &&
        d.name.toLowerCase().includes(search.toLowerCase())
    );
  }, [data, search, marketFilter]);

  // Select for comparison
  function toggleSelect(id) {
    setSelected((s) => {
      if (s.includes(id)) return s.filter((x) => x !== id);
      if (s.length >= 5) return s;
      return [...s, id];
    });
  }

  const compareRows = filtered.filter((d) =>
    selected.includes(d.id)
  );

  // Scatter data
  const scatterData = compareRows.map((d) => ({
    x: d[xTrait],
    y: d[yTrait],
    name: d.name,
  }));

  // Resistance score
  function resistanceScore(r) {
    const vals = Object.values(r).filter((v) => v);
    const resistant = vals.filter((v) => v === "R").length;
    return (resistant / vals.length).toFixed(2);
  }

  // Download CSV
  function downloadCSV(rows) {
    const flat = rows.map((r) => ({
      id: r.id,
      name: r.name,
      marketClass: r.marketClass,
      yield_kg_ha: r.yield_kg_ha,
	  maturity_days: r.maturity_days,
	  seed_weight_g: r.seed_weight_g,
	  harvestability: r.harvestability,
      resistance_score: resistanceScore(r.resistance),
    }));

    const keys = Object.keys(flat[0]);
    const csv = [
      keys.join(","),
      ...flat.map((r) => keys.map((k) => r[k]).join(",")),
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "uog_seed_catalog.csv";
    a.click();
  }

  return (
    <div style={{ padding: 30 }}>
      <h1>University of Guelph Seed Catalog</h1>

      {/* Controls */}
      <div style={{ marginBottom: 20 }}>
        <input
          placeholder="Search variety..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <select
          value={marketFilter}
          onChange={(e) => setMarketFilter(e.target.value)}
        >
          {marketClasses.map((m) => (
            <option key={m}>{m}</option>
          ))}
        </select>

        <button onClick={() => downloadCSV(filtered)}>
          Download filtered CSV
        </button>
      </div>

      {/* Trait selectors */}
      <div style={{ marginBottom: 20 }}>
        X-axis:
        <select onChange={(e) => setXTrait(e.target.value)}>
          {traitOptions.map((t) => (
            <option key={t.key} value={t.key}>
              {t.label}
            </option>
          ))}
        </select>

        Y-axis:
        <select onChange={(e) => setYTrait(e.target.value)}>
          {traitOptions.map((t) => (
            <option key={t.key} value={t.key}>
              {t.label}
            </option>
          ))}
        </select>
      </div>

      {/* Cards */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: 20 }}>
        {filtered.map((v) => (
          <div
            key={v.id}
            style={{
              border: "1px solid #ccc",
              width: 260,
              padding: 10,
              cursor: "pointer",
            }}
            onClick={() => setActiveVariety(v)}
          >
            <img
              src={v.imageUrl}
              alt={v.name}
              style={{ width: "100%", height: 150, objectFit: "cover" }}
              onError={(e) =>
                (e.target.src =
                  "https://via.placeholder.com/250x150?text=No+Image")
              }
            />

            <h3>{v.name}</h3>
            <p>{v.marketClass}</p>
            <p>Yield: {v.yield_kg_ha}</p>
            <p>Maturity: {v.maturity_days}</p>
            <p>
              Resistance score:{" "}
              {resistanceScore(v.resistance)}
            </p>

            <label>
              <input
                type="checkbox"
                checked={selected.includes(v.id)}
                onChange={(e) => {
                  e.stopPropagation();
                  toggleSelect(v.id);
                }}
              />
              Compare
            </label>
          </div>
        ))}
      </div>

      {/* Scatter plot */}
      <h2 style={{ marginTop: 40 }}>Trait Comparison</h2>

      {scatterData.length > 0 && (
        <ResponsiveContainer width="100%" height={350}>
          <ScatterChart>
            <CartesianGrid />
            <XAxis
              type="number"
              dataKey="x"
              name={xTrait}
            />
            <YAxis
              type="number"
              dataKey="y"
              name={yTrait}
            />
            <Tooltip />
            <Legend />
            {scatterData.map((d, i) => (
              <Scatter
                key={i}
                name={d.name}
                data={[d]}
                fill={`hsl(${i * 60},70%,50%)`}
              />
            ))}
          </ScatterChart>
        </ResponsiveContainer>
      )}

      {/* Detail modal */}
      {activeVariety && (
        <div
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: "rgba(0,0,0,0.7)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
          onClick={() => setActiveVariety(null)}
        >
          <div
            style={{
              background: "white",
              padding: 20,
              width: 600,
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h2>{activeVariety.name}</h2>
            <img
              src={activeVariety.imageUrl}
              style={{ width: "100%" }}
            />

            <h3>Traits</h3>
            <pre>
              {JSON.stringify(
                activeVariety,
                null,
                2
              )}
            </pre>

            <h3>Resistance</h3>
            <pre>
              {JSON.stringify(
                activeVariety.resistance,
                null,
                2
              )}
            </pre>

            <button onClick={() => setActiveVariety(null)}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}